.eyebrow{color:var(--accent);font:9px/1.6 Arial,sans-serif;letter-spacing:.1em}.eyebrow:before{width:20px;background:var(--accent);height:1px}.btn{background:var(--ink);color:var(--paper);border:1px solid var(--ink);border-radius:0;font-size:12px;font-weight:400;padding:14px 20px;min-height:47px}.btn:hover{background:var(--accent);border-color:var(--accent)}.btn.outline{color:var(--ink);border-color:var(--line)}.text-link{border-bottom:1px solid var(--accent);color:var(--ink)}
