-button:disabled{cursor:default;opacity:.45}.provider-button svg{width:20px;height:23px;fill:currentColor}.provider-symbol{font-weight:600;font-size:22px}.account-unavailable{padding:12px 14px;border-left:2px solid var(--line)}.account-panel p.account-fine{font-size:10px;line-height:1.9}.account-panel .text-link{font-size:11px}.account-actions{display:flex;align-items:center;gap:25px}.visit-choice{display:flex;align-items:center;gap:9px;margin:24px 0 10px;font-size:12px}.visit-choice input{width:16px;height:16px;accent-color:#229EC4}.account-error{color:#9D4055!important;font-size:11px;line-height:1.8;white-space:pre-wrap}.visitor-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin:0 0 28px}.visitor-stats article{border:1px solid var(--line);padding:23px}.visitor-stats span{display:block;font-size:10px;color:var(--muted)}.visitor-stats strong{display:block;font:40px/1.4 Arial,sans-serif;margin-top:12px;font-weight:400}.admin-toolbar{display:flex;align-items:center;gap:22px;margin:20px 0}.admin-toolbar p{font-size:11px;color:var(--muted);line-height:1.9;margin-right:auto;max-width:650px}.admin-toolbar button{white-space:nowrap;font-size:11px}.visitor-table{overflow-x:auto;border:1px solid var(--line)}.visitor-table table{width:100%;border-collapse:collapse;min-width:620px;text-align:left;font:11px/1.7 Arial,CLFNBody,sans-serif}.visitor-table th{font-weight:400;color:var(--muted);font-size:10px;background:#F5F1E8}.visitor-table td,.visitor-table th{padding:13px 16px;border-bottom:1px solid var(--line);vertical-align:top}.visitor-table td small{display:block;font-size:10px;color:var(--muted)}
